describe('Notification Preferences Management', () => {
  beforeEach(() => {
    cy.visit('/settings');
  });

  it('should successfully manage notification preferences', () => {
    // Verify settings page loads
    cy.get('[data-testid="settings-page"]').should('be.visible');
    cy.get('[data-testid="notification-preferences-section"]').should('be.visible');

    // Verify default notification settings are visible
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');
    cy.get('[data-testid="sms-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');

    // Toggle email notifications off
    cy.get('[data-testid="email-notifications-toggle"]').click();
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');
    cy.get('[data-testid="email-notifications-label"]').should('contain', 'Email notifications');

    // Toggle SMS notifications on
    cy.get('[data-testid="sms-notifications-toggle"]').click();
    cy.get('[data-testid="sms-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');

    // Toggle push notifications off
    cy.get('[data-testid="push-notifications-toggle"]').click();
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');

    // Verify save button is visible and enabled
    cy.get('[data-testid="save-preferences-button"]').should('be.visible').should('not.be.disabled');

    // Click save button
    cy.get('[data-testid="save-preferences-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Preferences saved successfully');

    // Verify settings page remains visible
    cy.get('[data-testid="settings-page"]').should('be.visible');
  });

  it('should handle edge case of disabling all notification types', () => {
    // Verify initial state
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');
    cy.get('[data-testid="sms-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'true');

    // Disable email notifications
    cy.get('[data-testid="email-notifications-toggle"]').click();
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');

    // Disable SMS notifications
    cy.get('[data-testid="sms-notifications-toggle"]').click();
    cy.get('[data-testid="sms-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');

    // Disable push notifications
    cy.get('[data-testid="push-notifications-toggle"]').click();
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');

    // Verify save button is still available
    cy.get('[data-testid="save-preferences-button"]').should('be.visible');

    // Click save button
    cy.get('[data-testid="save-preferences-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Preferences saved successfully');

    // Verify all toggles are in off state
    cy.get('[data-testid="email-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');
    cy.get('[data-testid="sms-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');
    cy.get('[data-testid="push-notifications-toggle"]').should('have.attr', 'aria-checked', 'false');
  });
});
